-- Official mechanics and every level a feature is gained at (#976).
--
-- Why: the adoption in 20261005181018 leaves an official feature with only the
-- `activation` derived from the old `feature_type`. Its uses, scaling, riders,
-- toggles and choices, the feat columns, and the levels a feature is gained at
-- (the old importer kept `gained_at[0]` only, so the 2014 Rogue had its Ability
-- Score Improvement at level 10 and nowhere else) came only from the admin
-- import. A release must not wait for that click.
--
-- This is the import's own plan (src/lib/library/officialClassContent.ts) run
-- offline against Open5e v2 and the SRD catalogues, as SQL. Generated by
-- scripts/official-mechanics-sql.ts on 5 Oct 2026; regenerate rather than edit.
--
-- It follows the same rules as the import and no others:
--   - a field is written only while the row still holds what the import last
--     wrote (`provenance.imported`), or is empty with no baseline; the baseline
--     moves for the fields written, so an admin's edit survives;
--   - a feature map is only added to: an id is appended at a level when absent,
--     nothing is removed or reordered, a hand-added id stays;
--   - rows that do not exist (a fresh database, content not adopted) are not
--     matched, and nothing outside official rows (`user_id is null`) is touched.
-- The admin import stays as an optional refresh and respects the same baseline.
--
-- `private.apply_official_mechanics_backfill()` stays in place, revoked from
-- client roles, so supabase/tests/official_mechanics_backfill.test.sql can call
-- it on fixtures.

-- BEGIN GENERATED BY scripts/official-mechanics-sql.ts
create function private.union_feature_maps(p_current jsonb, p_incoming jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $fn$
  -- Every level of either map; at each, the current ids in their order, then the
  -- incoming ids that are not there yet. Nothing is removed or reordered.
  select coalesce(jsonb_object_agg(l.lvl, (
    select coalesce(jsonb_agg(u.id order by u.ord), '[]'::jsonb)
      from (
        select id, min(ord) as ord
          from (
            select e.value as id, e.ordinality as ord
              from jsonb_array_elements_text(coalesce(p_current -> l.lvl, '[]'::jsonb)) with ordinality as e(value, ordinality)
            union all
            select e.value, 1000000 + e.ordinality
              from jsonb_array_elements_text(coalesce(p_incoming -> l.lvl, '[]'::jsonb)) with ordinality as e(value, ordinality)
          ) all_ids
         group by id
      ) u
  )), '{}'::jsonb)
    from (
      select jsonb_object_keys(coalesce(p_current, '{}'::jsonb)) as lvl
      union
      select jsonb_object_keys(coalesce(p_incoming, '{}'::jsonb))
    ) l;
$fn$;

