    from (select doc, rec, nullif(rs, '') as rs, m::jsonb as mechanics
            from (values
    ('srd-2024', 'srd-2024_barbarian_ability-score-improvement', '2024', '{"choices":[{"key":"ability_score_improvement","label":"Ability Score Improvement","pick":{"kind":"feat","categories":["general"]},"count":{"kind":"per_grant","amount":1},"replace_on_level_up":false}]}'),
