    ('srd-2014', 'srd_way-of-the-open-hand_wholeness-of-body', '2014', '{"activation":"action","uses":{"key":"wholeness_of_body","label":"Wholeness of Body","amount":{"kind":"fixed","value":1},"recharge":"long","pool":false}}'),
    ('srd-2014', 'srd_wizard_ability-score-improvement', '2014', '{"choices":[{"key":"ability_score_improvement","label":"Ability Score Improvement","pick":{"kind":"asi_or_feat"},"count":{"kind":"per_grant","amount":1},"replace_on_level_up":false}]}'),
    ('srd-2014', 'srd_wizard_arcane-recovery', '2014', '{"activation":"special","uses":{"key":"arcane_recovery","label":"Arcane Recovery","amount":{"kind":"fixed","value":1},"recharge":"long","pool":false}}')
          ) as t(doc, rec, rs, m)) v
   where f.user_id is null
     and f.source_document_key = v.doc and f.source_record_key = v.rec
     and f.ruleset is not distinct from v.rs
     and f.mechanics is distinct from v.mechanics
     and case when f.provenance -> 'imported' ? 'mechanics' then f.mechanics is not distinct from nullif(f.provenance -> 'imported' -> 'mechanics', 'null'::jsonb) else f.mechanics = '{}'::jsonb end;

  -- Feats: category, prerequisites, repeatable, ability increase and mechanics, each
  -- written only while its field is still the import's own. kind goes with them,
  -- because the feat-only columns are refused on a row that is not a feat.
  update public.class_features f
     set kind = 'feat',
         mechanics = case when x.ok_mechanics then x.mechanics else f.mechanics end,
         feat_category = case when x.ok_feat_category then x.feat_category else f.feat_category end,
         prerequisites = case when x.ok_prerequisites then x.prerequisites else f.prerequisites end,
         repeatable = case when x.ok_repeatable then x.repeatable else f.repeatable end,
         ability_increase = case when x.ok_ability_increase then x.ability_increase else f.ability_increase end,
         provenance = coalesce(f.provenance, '{}'::jsonb)
           || jsonb_build_object('imported', coalesce(f.provenance -> 'imported', '{}'::jsonb)
             || case when x.ok_mechanics then jsonb_build_object('mechanics', x.mechanics) else '{}'::jsonb end
             || case when x.ok_feat_category then jsonb_build_object('feat_category', x.feat_category) else '{}'::jsonb end
             || case when x.ok_prerequisites then jsonb_build_object('prerequisites', x.prerequisites) else '{}'::jsonb end
             || case when x.ok_repeatable then jsonb_build_object('repeatable', x.repeatable) else '{}'::jsonb end
             || case when x.ok_ability_increase then jsonb_build_object('ability_increase', x.ability_increase) else '{}'::jsonb end)
    from (
      select f.id, v.mechanics, v.feat_category, v.prerequisites, v.repeatable, v.ability_increase,
             -- An empty plan says nothing about mechanics; keep what is there.
             (v.mechanics <> '{}'::jsonb and case when f.provenance -> 'imported' ? 'mechanics' then f.mechanics is not distinct from nullif(f.provenance -> 'imported' -> 'mechanics', 'null'::jsonb) else f.mechanics = '{}'::jsonb end) as ok_mechanics,
             (case when f.provenance -> 'imported' ? 'feat_category' then f.feat_category is not distinct from (f.provenance -> 'imported' ->> 'feat_category') else f.feat_category is null end) as ok_feat_category,
             (case when f.provenance -> 'imported' ? 'prerequisites' then f.prerequisites is not distinct from nullif(f.provenance -> 'imported' -> 'prerequisites', 'null'::jsonb) else f.prerequisites is null end) as ok_prerequisites,
             (case when f.provenance -> 'imported' ? 'repeatable' then f.repeatable is not distinct from (f.provenance -> 'imported' ->> 'repeatable')::boolean else not f.repeatable end) as ok_repeatable,
             (case when f.provenance -> 'imported' ? 'ability_increase' then f.ability_increase is not distinct from nullif(f.provenance -> 'imported' -> 'ability_increase', 'null'::jsonb) else f.ability_increase is null end) as ok_ability_increase
        from public.class_features f
        join (select doc, rec, nullif(rs, '') as rs, m::jsonb as mechanics, fc as feat_category,
                     p::jsonb as prerequisites, r::boolean as repeatable, a::jsonb as ability_increase
                from (values
    ('srd-2024', 'srd-2024_ability-score-improvement', '2024', '{}', 'general', '{"level":4}', 'true', '{"abilities":["str","dex","con","int","wis","cha"],"amount":2,"split":true,"max":20}'),
