    ('srd-2024', 'srd-2024_boon-of-irresistible-offense', '2024', '{}', 'epic_boon', '{"level":19}', 'false', '{"abilities":["str","dex","con","int","wis","cha"],"amount":1,"split":false,"max":30}'),
